import pandas as pd, glob, os
for f in glob.glob('airlines/*.csv'):
 d=pd.read_csv(f).drop_duplicates('flight_id'); utc='date_utc' in d.columns; s='sched_dep_utc' if utc else 'sched_dep'; a='actual_dep_utc' if utc else 'actual_dep'
 x=d[(~d.cancelled)&d[a].notna()].copy();
 def mins(v): return int(v[:2])*60+int(v[3:])
 x['raw']=x[a].map(mins)-x[s].map(mins)
 neg=x[x.raw<0]
 print(os.path.basename(f), 'negative',len(neg), 'raw values', sorted(neg.raw.unique())[:20], 'large',neg[neg.raw<-120][[s,a,'raw']].to_dict('records')[:10])

